/// <summary>
///  PaffH 24.11.25
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
/// <returns>boolean</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    ret = super(_entityCtx, _dataSourceCtx);

    this.writeDatasourcesExclusiveRoot(_entityCtx, _dataSourceCtx);

    return ret;
}

/// <summary>
///  PaffH 24.11.25
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
/// <returns>boolean</returns>
public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    ret = super(_entityCtx, _dataSourceCtx);

    this.writeDatasourcesExclusiveRoot(_entityCtx, _dataSourceCtx);

    return ret;
}

/// <summary>
///  PaffH 24.11.25
/// save changes to NDXBVEMailRequestLineItemAIDecisionBasis and NDXBVEMailRequestLineItemAIInfo
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
protected void writeDatasourcesExclusiveRoot(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    NDXBVEMailRequestLineItem nDXBVEMailRequestLineItem = _dataSourceCtx.getBuffer();
    if (NDXBVEMailRequestLineItem::exists(nDXBVEMailRequestLineItem.RecId))
    {
        DataEntityDataSourceRuntimeContext deDsContext = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(NDXBVEMailRequestLineItemEntity, NDXBVEMailRequestLineItemAIDecisionBasis));
        if (deDsContext)
        {
            NDXBVEMailRequestLineItemAIDecisionBasis buffer = deDsContext.getBuffer();
            NDXBVEMailRequestLineItemAIDecisionBasis nDXBVEMailRequestLineItemAIDecisionBasis = NDXBVEMailRequestLineItemAIDecisionBasis::findOrCreate(nDXBVEMailRequestLineItem.RecId);
            nDXBVEMailRequestLineItemAIDecisionBasis.initFromNDXBVEMailRequestLineItemAIDecisionBasis(buffer);
            if (nDXBVEMailRequestLineItemAIDecisionBasis.validateWrite())
            {
                ttsbegin;
                nDXBVEMailRequestLineItemAIDecisionBasis.write();
                ttscommit;
            }
        }
        deDsContext = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(NDXBVEMailRequestLineItemEntity, NDXBVEMailRequestLineItemAIInfo));
        if (deDsContext)
        {
            NDXBVEMailRequestLineItemAIInfo buffer = deDsContext.getBuffer();
            NDXBVEMailRequestLineItemAIInfo nDXBVEMailRequestLineItemAIInfo = NDXBVEMailRequestLineItemAIInfo::findOrCreate(nDXBVEMailRequestLineItem.RecId);
            nDXBVEMailRequestLineItemAIInfo.initFromNDXBVEMailRequestLineItemAIInfo(buffer);
            if (nDXBVEMailRequestLineItemAIInfo.validateWrite())
            {
                ttsbegin;
                nDXBVEMailRequestLineItemAIInfo.write();
                ttscommit;
            }
        }
    }
}
